//! Syntax for Artifex (dev-tools.md §3.4, plan M11/P6): tree-sitter
//! grammars vendored as crates (all MIT), parsed in-process with a time
//! budget, edited incrementally from the buffer's edit log, and turned into
//! the [`pergola::code::Span`]s the code grid colours.
//!
//! Grammars are C code generated by tree-sitter, run on text the person
//! opened. A grammar crash takes Artifex down with it, so the parse has a
//! budget (a hostile file can't hang the editor) and Artifex's fuzz panel
//! (M12) fuzzes these parsers like any other input surface.

use std::ops::Range;
use std::path::Path;
use std::time::{Duration, Instant};

use pergola::code::{Edit, Highlight, Span, Tag};
use ropey::Rope;
use streaming_iterator::StreamingIterator;
use tree_sitter::{InputEdit, Language, Node, ParseOptions, Parser, Point, Query, QueryCursor, Tree};

/// The languages Artifex highlights.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Lang {
    Rust,
    C,
    Cpp,
    Toml,
    Markdown,
    Shell,
    Python,
    Json,
}

impl Lang {
    pub const ALL: [Lang; 8] =
        [Lang::Rust, Lang::C, Lang::Cpp, Lang::Toml, Lang::Markdown, Lang::Shell, Lang::Python, Lang::Json];

    /// The language of a file, from its name.
    pub fn from_path(path: &Path) -> Option<Lang> {
        let name = path.file_name()?.to_str()?;
        match name {
            "Cargo.lock" => return Some(Lang::Toml),
            "Makefile" | "GNUmakefile" | "BSDmakefile" => return None,
            ".profile" | ".bashrc" | ".shrc" | ".kshrc" | ".zshrc" => return Some(Lang::Shell),
            _ => {}
        }
        let ext = path.extension()?.to_str()?.to_ascii_lowercase();
        Some(match ext.as_str() {
            "rs" => Lang::Rust,
            "c" | "h" => Lang::C,
            "cc" | "cpp" | "cxx" | "hh" | "hpp" | "hxx" => Lang::Cpp,
            "toml" => Lang::Toml,
            "md" | "markdown" => Lang::Markdown,
            "sh" | "bash" | "ksh" | "zsh" => Lang::Shell,
            "py" | "pyi" => Lang::Python,
            "json" => Lang::Json,
            _ => return None,
        })
    }

    /// The language a `#!` first line names.
    pub fn from_shebang(first: &str) -> Option<Lang> {
        let rest = first.strip_prefix("#!")?;
        let mut words = rest.split_whitespace();
        let mut prog = words.next()?.rsplit('/').next()?;
        if prog == "env" {
            prog = words.find(|w| !w.starts_with('-'))?;
        }
        match prog {
            "sh" | "bash" | "ksh" | "zsh" | "dash" => Some(Lang::Shell),
            p if p.starts_with("python") => Some(Lang::Python),
            _ => None,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Lang::Rust => "Rust",
            Lang::C => "C",
            Lang::Cpp => "C++",
            Lang::Toml => "TOML",
            Lang::Markdown => "Markdown",
            Lang::Shell => "Shell",
            Lang::Python => "Python",
            Lang::Json => "JSON",
        }
    }

    /// The line-comment prefix "Toggle comment" uses, if the language has one.
    pub fn comment(self) -> Option<&'static str> {
        match self {
            Lang::Rust | Lang::C | Lang::Cpp => Some("//"),
            Lang::Toml | Lang::Shell | Lang::Python => Some("#"),
            Lang::Markdown | Lang::Json => None,
        }
    }

    fn language(self) -> Language {
        match self {
            Lang::Rust => tree_sitter_rust::LANGUAGE.into(),
            Lang::C => tree_sitter_c::LANGUAGE.into(),
            Lang::Cpp => tree_sitter_cpp::LANGUAGE.into(),
            Lang::Toml => tree_sitter_toml_ng::LANGUAGE.into(),
            // Block structure only for now: inline markup is a second
            // grammar injected per paragraph.
            Lang::Markdown => tree_sitter_md::LANGUAGE.into(),
            Lang::Shell => tree_sitter_bash::LANGUAGE.into(),
            Lang::Python => tree_sitter_python::LANGUAGE.into(),
            Lang::Json => tree_sitter_json::LANGUAGE.into(),
        }
    }

    fn highlights(self) -> String {
        match self {
            Lang::Rust => tree_sitter_rust::HIGHLIGHTS_QUERY.into(),
            Lang::C => tree_sitter_c::HIGHLIGHT_QUERY.into(),
            // C++'s query only adds to C's.
            Lang::Cpp => format!("{}\n{}", tree_sitter_c::HIGHLIGHT_QUERY, tree_sitter_cpp::HIGHLIGHT_QUERY),
            Lang::Toml => tree_sitter_toml_ng::HIGHLIGHTS_QUERY.into(),
            Lang::Markdown => tree_sitter_md::HIGHLIGHT_QUERY_BLOCK.into(),
            Lang::Shell => tree_sitter_bash::HIGHLIGHT_QUERY.into(),
            Lang::Python => tree_sitter_python::HIGHLIGHTS_QUERY.into(),
            Lang::Json => tree_sitter_json::HIGHLIGHTS_QUERY.into(),
        }
    }
}

#[derive(Debug)]
pub enum Error {
    /// The grammar was built for another tree-sitter ABI.
    Language(tree_sitter::LanguageError),
    /// The bundled highlight query doesn't compile against its grammar.
    Query(tree_sitter::QueryError),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::Language(e) => write!(f, "grammar: {e}"),
            Error::Query(e) => write!(f, "highlight query: {e}"),
        }
    }
}

impl std::error::Error for Error {}

/// How long one parse may run before Artifex gives up on it and keeps the
/// last tree (the file stays editable, colours may lag).
pub const PARSE_BUDGET: Duration = Duration::from_millis(150);

/// Captures examined per highlight request at most: a query over a
/// pathological tree mustn't stall a frame.
const CAPTURE_BUDGET: usize = 200_000;

/// One open file's syntax tree.
pub struct Syntax {
    lang: Lang,
    parser: Parser,
    query: Query,
    names: Vec<Tag>,
    tree: Option<Tree>,
    budget: Duration,
    stale: bool,
}

impl Syntax {
    pub fn new(lang: Lang) -> Result<Syntax, Error> {
        let language = lang.language();
        let mut parser = Parser::new();
        parser.set_language(&language).map_err(Error::Language)?;
        let query = Query::new(&language, &lang.highlights()).map_err(Error::Query)?;
        let names = query.capture_names().iter().map(|n| Tag::from_capture(n)).collect();
        Ok(Syntax { lang, parser, query, names, tree: None, budget: PARSE_BUDGET, stale: true })
    }

    pub fn lang(&self) -> Lang {
        self.lang
    }

    pub fn set_budget(&mut self, budget: Duration) {
        self.budget = budget;
    }

    /// Whether the tree lags the text (the last parse ran out of time).
    pub fn stale(&self) -> bool {
        self.stale
    }

    pub fn tree(&self) -> Option<&Tree> {
        self.tree.as_ref()
    }

    /// Parse `text` from scratch. False when the parse ran out of time.
    pub fn parse(&mut self, text: &Rope) -> bool {
        self.tree = None;
        self.reparse(text)
    }

    /// Follow `edits` (from [`pergola::code::CodeBuffer::take_edits`], in
    /// order) and reparse what they touched. False when the parse ran out
    /// of time; the old tree, shifted by the edits, stays in use.
    pub fn edit(&mut self, text: &Rope, edits: &[Edit]) -> bool {
        if let Some(tree) = &mut self.tree {
            for e in edits {
                tree.edit(&input_edit(e));
            }
        }
        self.reparse(text)
    }

    fn reparse(&mut self, text: &Rope) -> bool {
        let len = text.len_bytes();
        let mut read = |byte: usize, _: Point| -> &[u8] {
            if byte >= len {
                return &[];
            }
            let (chunk, start, _, _) = text.chunk_at_byte(byte);
            &chunk.as_bytes()[byte - start..]
        };
        let deadline = Instant::now() + self.budget;
        let mut progress = |_: &tree_sitter::ParseState| Instant::now() >= deadline;
        let options = ParseOptions::new().progress_callback(&mut progress);
        match self.parser.parse_with_options(&mut read, self.tree.as_ref(), Some(options)) {
            Some(tree) => {
                self.tree = Some(tree);
                self.stale = false;
                true
            }
            None => {
                // A halted parse leaves state for resuming the same text;
                // the next parse is of different text.
                self.parser.reset();
                self.stale = true;
                false
            }
        }
    }

    /// Highlighting for `lines` (the ones on screen).
    pub fn highlight(&self, text: &Rope, lines: Range<usize>) -> LineSpans {
        let last = lines.end.min(text.len_lines());
        let first = lines.start.min(last);
        let mut out = LineSpans { first, lines: Vec::with_capacity(last - first) };
        let Some(tree) = &self.tree else {
            out.lines.resize(last - first, Vec::new());
            return out;
        };
        let start_byte = text.line_to_byte(first);
        let end_byte = text.line_to_byte(last);

        // Every capture touching the range, painted bigger nodes first so
        // inner nodes win; for one node, the earliest pattern wins (the
        // order these query files are written for).
        let mut hits: Vec<(usize, usize, usize, Tag)> = Vec::new();
        let mut cursor = QueryCursor::new();
        cursor.set_byte_range(start_byte..end_byte);
        let provider = |node: Node<'_>| {
            let r = node.byte_range();
            let r = r.start.min(text.len_bytes())..r.end.min(text.len_bytes());
            text.byte_slice(r).chunks().map(str::as_bytes)
        };
        let mut captures = cursor.captures(&self.query, tree.root_node(), provider);
        let mut seen = 0usize;
        while let Some((m, i)) = captures.next() {
            seen += 1;
            if seen > CAPTURE_BUDGET {
                break;
            }
            let c = m.captures[*i];
            let tag = self.names[c.index as usize];
            if tag == Tag::Plain {
                continue;
            }
            let r = c.node.byte_range();
            hits.push((r.start, r.end, m.pattern_index, tag));
        }
        hits.sort_by(|a, b| (b.1 - b.0).cmp(&(a.1 - a.0)).then(b.2.cmp(&a.2)));

        let mut paint: Vec<Tag> = vec![Tag::Plain; end_byte - start_byte];
        for (s, e, _, tag) in hits {
            let s = s.clamp(start_byte, end_byte) - start_byte;
            let e = e.clamp(start_byte, end_byte) - start_byte;
            paint[s..e].fill(tag);
        }

        for line in first..last {
            let l0 = text.line_to_byte(line) - start_byte;
            let mut spans: Vec<Span> = Vec::new();
            let mut col = 0usize;
            let mut byte = l0;
            for ch in text.line(line).chars() {
                if ch == '\n' || ch == '\r' {
                    break;
                }
                let tag = paint[byte];
                if tag != Tag::Plain {
                    match spans.last_mut() {
                        Some(s) if s.tag == tag && s.cols.end == col => s.cols.end = col + 1,
                        _ => spans.push(Span { cols: col..col + 1, tag }),
                    }
                }
                byte += ch.len_utf8();
                col += 1;
            }
            out.lines.push(spans);
        }
        out
    }
}

fn input_edit(e: &Edit) -> InputEdit {
    InputEdit {
        start_byte: e.start_byte,
        old_end_byte: e.old_end_byte,
        new_end_byte: e.new_end_byte,
        start_position: Point::new(e.start.row, e.start.col_byte),
        old_end_position: Point::new(e.old_end.row, e.old_end.col_byte),
        new_end_position: Point::new(e.new_end.row, e.new_end.col_byte),
    }
}

/// Spans for a run of lines, as the grid asks for them.
#[derive(Debug, Clone, Default)]
pub struct LineSpans {
    first: usize,
    lines: Vec<Vec<Span>>,
}

impl LineSpans {
    pub fn covers(&self, lines: &Range<usize>) -> bool {
        self.first <= lines.start && lines.end <= self.first + self.lines.len()
    }
}

impl Highlight for LineSpans {
    fn line(&self, line: usize) -> Vec<Span> {
        line.checked_sub(self.first).and_then(|i| self.lines.get(i)).cloned().unwrap_or_default()
    }
}

